import {createMarshmallowPose,marshmallowPoseFrame} from '../marshmallow/pose.js';
import {FISH_GRILL} from './cooking-layout.js';
import * as THREE from 'three';import {createToyKit,disposeToyTree} from '../world/toy-kit.js';import {createFish} from './view.js';import {createFishPlatter} from './platter.js';
export function createFishCookingView({scene,zoneRoot,player,model,poser,visual,reduced=false,mode='home'}){
 const saved={parent:player.parent,position:player.position.clone(),quaternion:player.quaternion.clone(),scale:player.scale.clone(),mp:model.position.clone(),mq:model.quaternion.clone(),ms:model.scale.clone(),pose:poser.getState(),children:player.children.map(o=>[o,o.visible]),old:[]};const root=new THREE.Group();root.name='fish-cooking';zoneRoot.add(root);const camp=mode==='camp';if(camp){root.position.set(FISH_GRILL.station.x,FISH_GRILL.station.y,FISH_GRILL.station.z);root.rotation.y=FISH_GRILL.station.yaw;const old=zoneRoot.getObjectByName('camp.fish-grill');if(old){saved.old.push([old,old.visible]);old.visible=false;}}const k=createToyKit(root),{box,cylinder,sphere}=k;
 for(const mesh of Object.values(visual?.kitchen??{}).flat())if(mesh?.isObject3D){saved.old.push([mesh,mesh.visible]);mesh.visible=false;}
 const step=box(1.55,.44,1.10,'#a8bda5',0,.22,-1.02,.06);const stepTop=box(1.57,.035,1.12,'#d6dec0',0,.458,-1.02,.03);box(2.8,.055,1.02,'#d4b38b',0,1.19,-2.06,.045);
 if(camp){step.visible=stepTop.visible=false;for(const x of [-1.1,1.1])for(const z of [-2.4,-1.7])cylinder(.035,.04,.74,'#718982',x,.81,z);}
 const pan=cylinder(.61,.57,.075,'#58686b',.50,1.275,-2.10),inside=cylinder(.55,.55,.012,'#728181',.50,1.319,-2.10),bowl=cylinder(.37,.29,.16,'#8fb7b5',-.66,1.29,-2.10),water=cylinder(.32,.31,.012,'#b1d9df',-.66,1.38,-2.10);
 const heat=new THREE.Mesh(new THREE.TorusGeometry(.49,.025,6,24),k.mat('#f0ac52'));heat.rotation.x=Math.PI/2;heat.position.set(.5,1.227,-2.1);root.add(heat);
 const bite=sphere(.075,'#e5ba74',0,0,0,1,.55,.7);bite.name='fish-cook.bite';bite.visible=false;
 const handle=cylinder(.028,.033,1,'#9d7852',0,0,0);handle.name='fish-cook.pan-handle';const grip=new THREE.Group();grip.name='fish-cook.spatula-grip';root.add(grip);const shaft=cylinder(.019,.019,1,'#bb9366',0,0,0,grip),blade=box(.19,.035,.18,'#d8ba86',0,0,0,.02,grip);
 zoneRoot.add(player);root.updateWorldMatrix(true,true);const place=camp?FISH_GRILL.player:{x:0,y:.49,z:-1.02},p=root.localToWorld(new THREE.Vector3(place.x,place.y,place.z));zoneRoot.worldToLocal(p);player.position.copy(p);player.rotation.set(0,Math.PI+(camp?FISH_GRILL.station.yaw:0),0);player.scale.setScalar(1);model.position.set(0,0,0);model.quaternion.identity();model.scale.setScalar(1);for(const[c]of saved.children)if(c!==model)c.visible=false;
 const camera=new THREE.OrthographicCamera(-2.6,2.6,2,-2,.05,100);root.updateWorldMatrix(true,true);camera.position.copy(root.localToWorld(new THREE.Vector3(-3,4.1,-4.9)));camera.lookAt(root.localToWorld(new THREE.Vector3(0,1.25,-1.65)));
 let eater=null,eatingStart=null,alive=true,state=null,fish=null,plate=null,fishId=null,clock=0,flip=0,lastSide=0,lastPose='',tints=[];const gold=new THREE.Color('#ddb77b'),burnt=new THREE.Color('#6b4939'),Y=new THREE.Vector3(0,1,0),left=new THREE.Vector3(),right=new THREE.Vector3(),target=new THREE.Vector3(),delta=new THREE.Vector3();
 function beam(mesh,a,b){mesh.position.copy(a).add(b).multiplyScalar(.5);mesh.scale.y=a.distanceTo(b);mesh.quaternion.setFromUnitVectors(Y,delta.copy(b).sub(a).normalize());}
 function draw(){if(!alive)return;const s=state;if(eater&&s?.phase==='complete'&&s.mode==='meal'){const elapsed=s.mealElapsed??0,f=marshmallowPoseFrame({phase:elapsed>=2.7?'done':'eating',elapsed,distance:.65}),u=Math.min(1,elapsed/.35);for(const side of ['left','right'])f.hands[side]=f.hands[side].map((n,i)=>eatingStart[side][i]+(n-eatingStart[side][i])*u);eater.update(f);player.updateWorldMatrix(true,true);root.updateWorldMatrix(true,true);right.fromArray(f.hands.right);player.localToWorld(right);root.worldToLocal(right);grip.position.copy(right);const tip=new THREE.Vector3(...f.hands.right).addScaledVector(new THREE.Vector3(...f.direction),f.gripToTip);player.localToWorld(tip);root.worldToLocal(tip);target.copy(tip).sub(right);beam(shaft,new THREE.Vector3(),target);blade.position.copy(target);bite.position.copy(tip);bite.scale.setScalar(f.foodScale);bite.visible=f.foodScale>.001;grip.visible=true;handle.visible=false;pan.visible=inside.visible=bowl.visible=water.visible=heat.visible=false;fish.visible=false;plate.visible=true;plate.position.set(.35,1.23,-2.05);plate.getObjectByName('fish.'+fishId).visible=elapsed<2.2;root.updateWorldMatrix(true,true);return;}bite.visible=false;handle.visible=true;const preparing=s?.phase==='prepare',cooking=s?.phase==='heat',finished=s&&['ready','complete'].includes(s.phase),pose=preparing&&s.busy?(s.step===1?'cookMix':'cookPour'):cooking?'cookPan':'cookReady',time=preparing&&s.busy&&!reduced?Math.floor(clock*12)/12:0,key=pose+'|'+time;if(key!==lastPose){poser.setPose(pose,1,time);lastPose=key;}player.updateWorldMatrix(true,true);root.updateWorldMatrix(true,true);for(const [v,id]of[[left,'leftHand'],[right,'rightHand']]){v.fromArray(poser.getAnchors()[id]);player.localToWorld(v);root.worldToLocal(v);}grip.position.copy(right);target.set(.50,1.50+(reduced?0:Math.sin(flip/.6*Math.PI)*.18),-2.10);target.sub(right);beam(shaft,new THREE.Vector3(),target);blade.position.copy(target);beam(handle,left,new THREE.Vector3(.50,1.295,-1.56));grip.visible=!!s&&(cooking||s.phase==='failed');heat.visible=cooking&&s.running;pan.visible=inside.visible=!finished;bowl.visible=water.visible=!finished;
  if(fish){fish.visible=!!s&&!finished;fish.rotation.set(Math.PI/2+(s?.side??0)*Math.PI+(reduced?0:Math.sin(flip/.6*Math.PI)*.25),0,0);fish.position.set(cooking||s?.phase==='failed'?.50:-.66,1.45,-2.10);if(preparing&&s.busy&&s.step===0){fish.position.copy(right);fish.rotation.set(0,Math.PI,0);}if(preparing&&s.busy&&s.step===2){const t=Math.min(1,s.elapsed);fish.position.x=-.66+1.16*t;fish.position.y+=Math.sin(t*Math.PI)*.15;}const heatValue=s?.sides?Math.max(...s.sides):0;for(const [material,color]of tints){material.color.copy(color).lerp(gold,Math.min(1,heatValue/9));if(heatValue>14)material.color.lerp(burnt,Math.min(1,(heatValue-14)/4));}}
  if(plate){plate.visible=finished;plate.position.set(.35,1.23,-2.05);}root.updateWorldMatrix(true,true);
 }
 return {root,camera,scene,update(next){if(!alive)return;if(eater&&(!next||next.phase!=='complete'||next.mode!=='meal')){eater.dispose();eater=null;lastPose='';if(plate)plate.getObjectByName('fish.'+fishId).visible=true;}if(next?.phase==='complete'&&next.mode==='meal'&&!eater){const a=poser.getAnchors();eatingStart={right:[...a.rightHand],left:[Math.abs(a.leftHand[0]),a.leftHand[1],a.leftHand[2]]};eater=createMarshmallowPose(model,poser,{seated:false});}state=next;if(next?.fishId&&next.fishId!==fishId){if(fish)disposeToyTree(fish);if(plate)disposeToyTree(plate);fishId=next.fishId;fish=createFish(fishId);plate=createFishPlatter(fishId);root.add(fish,plate);tints=[];const seen=new Set();fish.traverse(o=>{if(o.material&&!seen.has(o.material)){seen.add(o.material);if(!['294851','fff8e4'].includes(o.material.color.getHexString()))tints.push([o.material,o.material.color.clone()]);}});}if(next&&next.side!==lastSide){flip=.6;lastSide=next.side;}draw();},tick(dt){if(!alive)return;clock+=Math.max(0,Math.min(.1,dt));flip=Math.max(0,flip-dt);draw();},fit(width,height){const aspect=Math.max(.2,width/height),span=Math.max(3.5,4.9/aspect);Object.assign(camera,{left:-span*aspect/2,right:span*aspect/2,top:span/2,bottom:-span/2});camera.updateProjectionMatrix();},dispose(){if(!alive)return;alive=false;eater?.dispose();saved.parent.add(player);player.position.copy(saved.position);player.quaternion.copy(saved.quaternion);player.scale.copy(saved.scale);model.position.copy(saved.mp);model.quaternion.copy(saved.mq);model.scale.copy(saved.ms);poser.setPose(saved.pose.name,saved.pose.amount,saved.pose.time);for(const[o,v]of[...saved.children,...saved.old])o.visible=v;disposeToyTree(root);}};
}
